export const importCatalogContent = async (importInput: ImportInput, options?: Parameters<typeof customFetch>[1]): Promise<ImportResult> => {

  return customFetch<ImportResult>(getImportCatalogContentUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(importInput)
  }
);}





export const getImportCatalogContentMutationOptions = <TError = ErrorType<void>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof importCatalogContent>>, TError,{data: BodyType<ImportInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof importCatalogContent>>, TError,{data: BodyType<ImportInput>}, TContext> => {

const mutationKey = ['importCatalogContent'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof importCatalogContent>>, {data: BodyType<ImportInput>}> = (props) => {
          const {data} = props ?? {};

          return  importCatalogContent(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type ImportCatalogContentMutationResult = NonNullable<Awaited<ReturnType<typeof importCatalogContent>>>
    export type ImportCatalogContentMutationBody = BodyType<ImportInput>
    export type ImportCatalogContentMutationError = ErrorType<void>

    /**
 * @summary Upsert future MySQL catalogue records
 */
export const useImportCatalogContent = <TError = ErrorType<void>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof importCatalogContent>>, TError,{data: BodyType<ImportInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof importCatalogContent>>,
        TError,
        {data: BodyType<ImportInput>},
        TContext
      > => {
      return useMutation(getImportCatalogContentMutationOptions(options));
    }

